export function extractLinkedInUrl(result: { parsed_json?: any; linkedin_url?: string }): string | null {
  if (result.linkedin_url) return normalizeLinkedInUrl(result.linkedin_url);

  const pj = result.parsed_json;
  if (!pj) return null;

  if (typeof pj.linkedin === "string" && pj.linkedin) return normalizeLinkedInUrl(pj.linkedin);
  if (typeof pj.linkedin_url === "string" && pj.linkedin_url) return normalizeLinkedInUrl(pj.linkedin_url);
  if (pj.contact?.linkedin) return normalizeLinkedInUrl(pj.contact.linkedin);
  if (pj.contact?.linkedin_url) return normalizeLinkedInUrl(pj.contact.linkedin_url);
  if (pj.links?.linkedin) return normalizeLinkedInUrl(pj.links.linkedin);

  return null;
}

function normalizeLinkedInUrl(url: string): string {
  const trimmed = url.trim();
  if (trimmed.startsWith("http")) return trimmed;
  if (trimmed.startsWith("linkedin.com") || trimmed.startsWith("www.linkedin.com")) return "https://" + trimmed;
  if (trimmed.startsWith("in/")) return "https://www.linkedin.com/" + trimmed;
  return "https://www.linkedin.com/in/" + trimmed;
}

import { useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

export type NoteType = "general" | "positive" | "concern" | "flag";

export interface CandidateNote {
  id: string;
  resume_id: string;
  job_id: string;
  author_id: string;
  note_type: NoteType;
  content: string;
  created_at: string;
  updated_at: string;
}

export function useCandidateNotes(resumeId: string | null, jobId: string | null) {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const queryKey = ["candidate-notes", resumeId, jobId];

  const { data: notes = [], isLoading } = useQuery<CandidateNote[]>({
    queryKey,
    queryFn: async () => {
      if (!resumeId || !jobId) return [];
      const { data, error } = await (supabase as any)
        .from("candidate_notes")
        .select("*")
        .eq("resume_id", resumeId)
        .eq("job_id", jobId)
        .order("created_at", { ascending: false });
      if (error) throw error;
      return data ?? [];
    },
    enabled: !!resumeId && !!jobId,
    staleTime: 30_000,
  });

  useEffect(() => {
    if (!resumeId || !jobId) return;
    const channel = supabase
      .channel(`notes-${resumeId}-${jobId}`)
      .on("postgres_changes", {
        event: "*",
        schema: "public",
        table: "candidate_notes",
        filter: `resume_id=eq.${resumeId}`,
      }, () => {
        queryClient.invalidateQueries({ queryKey });
      })
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [resumeId, jobId, queryClient]);

  const addNote = useMutation({
    mutationFn: async ({ content, noteType }: { content: string; noteType: NoteType }) => {
      const { error } = await (supabase as any)
        .from("candidate_notes")
        .insert({ resume_id: resumeId, job_id: jobId, author_id: user?.id, note_type: noteType, content });
      if (error) throw error;
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey }),
  });

  const deleteNote = useMutation({
    mutationFn: async (noteId: string) => {
      const { error } = await (supabase as any)
        .from("candidate_notes")
        .delete()
        .eq("id", noteId);
      if (error) throw error;
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey }),
  });

  return { notes, isLoading, addNote, deleteNote, currentUserId: user?.id };
}

import { useState } from "react";
import { useCandidateNotes, type NoteType } from "@/hooks/useCandidateNotes";
import { useAuth } from "@/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { MessageSquare, Trash2, Loader2 } from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { cn } from "@/lib/utils";
import { toast } from "sonner";

const NOTE_TYPE_STYLES: Record<NoteType, { label: string; className: string }> = {
  general: { label: "General", className: "bg-muted text-muted-foreground" },
  positive: { label: "Positive", className: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400" },
  concern: { label: "Concern", className: "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400" },
  flag: { label: "Flag", className: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400" },
};

interface CandidateNotesPanelProps {
  resumeId: string;
  jobId: string;
}

export default function CandidateNotesPanel({ resumeId, jobId }: CandidateNotesPanelProps) {
  const { user } = useAuth();
  const { notes, isLoading, addNote, deleteNote, currentUserId } = useCandidateNotes(resumeId, jobId);
  const [content, setContent] = useState("");
  const [noteType, setNoteType] = useState<NoteType>("general");

  const handleSubmit = async () => {
    const trimmed = content.trim();
    if (!trimmed) return;
    try {
      await addNote.mutateAsync({ content: trimmed, noteType });
      setContent("");
      toast.success("Note added");
    } catch {
      toast.error("Failed to add note");
    }
  };

  const handleDelete = async (noteId: string) => {
    try {
      await deleteNote.mutateAsync(noteId);
      toast.success("Note deleted");
    } catch {
      toast.error("Failed to delete note");
    }
  };

  const getInitials = (authorId: string) => {
    if (authorId === user?.id) {
      const email = user?.email ?? "";
      const name = email.split("@")[0];
      return name.slice(0, 2).toUpperCase();
    }
    return authorId.slice(0, 2).toUpperCase();
  };

  return (
    <div className="rounded-xl border border-border overflow-hidden">
      {/* Panel header — matches StrengthsGapsPanel style */}
      <div className="bg-muted/60 px-4 py-2.5 flex items-center gap-2 border-b border-border">
        <MessageSquare className="h-4 w-4 text-muted-foreground" />
        <span className="text-sm font-semibold text-foreground">Team Notes</span>
        {notes.length > 0 && (
          <span className="ml-auto text-xs font-medium text-muted-foreground bg-muted px-2 py-0.5 rounded-full">
            {notes.length}
          </span>
        )}
      </div>

      <div className="p-4 space-y-3 bg-card">
        {/* Notes list */}
        {isLoading ? (
          <div className="flex items-center gap-2 text-xs text-muted-foreground py-2">
            <Loader2 className="h-3.5 w-3.5 animate-spin" /> Loading notes...
          </div>
        ) : notes.length > 0 ? (
          <div className="space-y-2 max-h-64 overflow-y-auto">
            {notes.map((note) => (
              <div key={note.id} className="rounded-lg border border-border bg-muted/20 p-3 space-y-1.5">
                <div className="flex items-center gap-2">
                  <div className="h-6 w-6 rounded-full bg-primary/10 text-primary flex items-center justify-center text-[10px] font-bold shrink-0">
                    {getInitials(note.author_id)}
                  </div>
                  <span className="text-xs text-muted-foreground truncate">
                    {note.author_id === currentUserId ? "You" : note.author_id.slice(0, 8)}
                  </span>
                  <span className="text-[10px] text-muted-foreground/60">
                    {formatDistanceToNow(new Date(note.created_at), { addSuffix: true })}
                  </span>
                  <span className={cn("text-[10px] px-1.5 py-0.5 rounded-full font-medium", NOTE_TYPE_STYLES[note.note_type as NoteType]?.className)}>
                    {NOTE_TYPE_STYLES[note.note_type as NoteType]?.label ?? note.note_type}
                  </span>
                  {note.author_id === currentUserId && (
                    <button
                      onClick={() => handleDelete(note.id)}
                      className="ml-auto text-muted-foreground/50 hover:text-destructive transition-colors"
                      aria-label="Delete note"
                    >
                      <Trash2 className="h-3 w-3" />
                    </button>
                  )}
                </div>
                <p className="text-sm text-foreground leading-relaxed">{note.content}</p>
              </div>
            ))}
          </div>
        ) : null}

        {/* Add note form */}
        <div className="space-y-2">
          <Textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Add a note..."
            className="min-h-[60px] text-sm resize-none"
            disabled={addNote.isPending}
          />
          <div className="flex items-center justify-between gap-2">
            <div className="flex items-center gap-1">
              {(Object.keys(NOTE_TYPE_STYLES) as NoteType[]).map((type) => (
                <button
                  key={type}
                  onClick={() => setNoteType(type)}
                  className={cn(
                    "text-[11px] px-2 py-1 rounded-full font-medium transition-all",
                    noteType === type
                      ? NOTE_TYPE_STYLES[type].className + " ring-1 ring-offset-1 ring-current"
                      : "bg-muted/50 text-muted-foreground hover:bg-muted"
                  )}
                >
                  {NOTE_TYPE_STYLES[type].label}
                </button>
              ))}
            </div>
            <Button
              size="sm"
              className="h-7 text-xs px-3"
              onClick={handleSubmit}
              disabled={!content.trim() || addNote.isPending}
            >
              {addNote.isPending ? <Loader2 className="h-3 w-3 animate-spin" /> : "Post"}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

